    "dockerfile": "FROM mshkn-base\nRUN mkdir -p /verb && printf '%s\\n' 'import json, os, sys, urllib.request' 'from pathlib import Path' 'query=sys.argv[1]' 'key=os.environ.get(\"TAVILY_API_KEY\", \"\").strip()' 'if not key:' '    candidates=[Path(\"/run/secrets/TAVILY_API_KEY\"),Path(\"/state/TAVILY_API_KEY\"),Path.cwd()/\"TAVILY_API_KEY\"]' '    for root in (Path(\"/mnt\"),Path(\"/workspace\"),Path(\"/chain\")):' '        if root.exists(): candidates.extend(root.rglob(\"TAVILY_API_KEY\"))' '    for p in candidates:' '        try:' '            if p.is_file():' '                key=p.read_text().strip()' '                if key: break' '        except (OSError, UnicodeError): pass' 'if not key:' '    print(json.dumps({\"error\":\"root-provisioned TAVILY_API_KEY not found on verb chain\"}))' '    raise SystemExit(1)' 'payload=json.dumps({\"api_key\":key,\"query\":query,\"search_depth\":\"basic\",\"max_results\":5,\"include_answer\":False,\"include_raw_content\":False,\"include_images\":False}).encode()' 'req=urllib.request.Request(\"https://api.tavily.com/search\",data=payload,headers={\"Content-Type\":\"application/json\"},method=\"POST\")' 'try:' '    with urllib.request.urlopen(req,timeout=20) as response: data=json.load(response)' 'except Exception as exc:' '    print(json.dumps({\"error\":\"Tavily request failed\",\"detail\":str(exc)}))' '    raise SystemExit(1)' 'results=[{\"title\":r.get(\"title\"),\"url\":r.get(\"url\"),\"content\":r.get(\"content\"),\"score\":r.get(\"score\")} for r in data.get(\"results\",[])[:5]]' 'print(json.dumps({\"query\":query,\"results\":results},ensure_ascii=False))' > /verb/run.py",
