    "dockerfile": "FROM golang:1.24-alpine AS build\nRUN printf '%s\\n' 'package main' 'import (\"bytes\"; \"encoding/json\"; \"fmt\"; \"io\"; \"net/http\"; \"os\"; \"strings\"; \"time\")' 'type Req struct { Query string `json:\"query\"`; MaxResults int `json:\"max_results\"`; SearchDepth string `json:\"search_depth\"`; IncludeAnswer bool `json:\"include_answer\"`; IncludeRawContent bool `json:\"include_raw_content\"` }' 'func main() {' ' q := os.Args[1]' ' key := strings.TrimSpace(os.Getenv(\"TAVILY_API_KEY\"))' ' if key == \"\" { for _, p := range []string{\"/run/secrets/TAVILY_API_KEY\", \"/state/TAVILY_API_KEY\", \"/state/secrets/TAVILY_API_KEY\", \"/data/TAVILY_API_KEY\"} { if b,e:=os.ReadFile(p); e==nil { key=strings.TrimSpace(string(b)); break } } }' ' if key == \"\" { fmt.Fprintln(os.Stderr,\"TAVILY_API_KEY is not available to web_search\"); os.Exit(2) }' ' body,_ := json.Marshal(Req{Query:q, MaxResults:5, SearchDepth:\"basic\", IncludeAnswer:false, IncludeRawContent:false})' ' req,e := http.NewRequest(\"POST\",\"https://api.tavily.com/search\",bytes.NewReader(body)); if e!=nil { panic(e) }' ' req.Header.Set(\"Content-Type\",\"application/json\"); req.Header.Set(\"Authorization\",\"Bearer \"+key)' ' c:=&http.Client{Timeout:20*time.Second}; resp,e:=c.Do(req); if e!=nil { fmt.Fprintln(os.Stderr,e); os.Exit(1) }; defer resp.Body.Close()' ' out,_:=io.ReadAll(io.LimitReader(resp.Body,2<<20)); if resp.StatusCode<200 || resp.StatusCode>=300 { fmt.Fprintf(os.Stderr,\"Tavily returned HTTP %d: %s\\n\",resp.StatusCode,string(out)); os.Exit(1) }; os.Stdout.Write(out)' '}' > /tmp/main.go && CGO_ENABLED=0 go build -o /web-search /tmp/main.go\nFROM mshkn-base\nCOPY --from=build /web-search /web-search",
